macro_rules! Shift {
    () => {
        # [doc = " A representation of the amount we're allowed to shift by during Two-Way"] # [doc = " search."] # [doc = ""] # [doc = " When computing a critical factorization of the needle, we find the position"] # [doc = " of the critical factorization by finding the needle's maximal (or minimal)"] # [doc = " suffix, along with the period of that suffix. It turns out that the period"] # [doc = " of that suffix is a lower bound on the period of the needle itself."] # [doc = ""] # [doc = " This lower bound is equivalent to the actual period of the needle in"] # [doc = " some cases. To describe that case, we denote the needle as `x` where"] # [doc = " `x = uv` and `v` is the lexicographic maximal suffix of `v`. The lower"] # [doc = " bound given here is always the period of `v`, which is `<= period(x)`. The"] # [doc = " case where `period(v) == period(x)` occurs when `len(u) < (len(x) / 2)` and"] # [doc = " where `u` is a suffix of `v[0..period(v)]`."] # [doc = ""] # [doc = " This case is important because the search algorithm for when the"] # [doc = " periods are equivalent is slightly different than the search algorithm"] # [doc = " for when the periods are not equivalent. In particular, when they aren't"] # [doc = " equivalent, we know that the period of the needle is no less than half its"] # [doc = " length. In this case, we shift by an amount less than or equal to the"] # [doc = " period of the needle (determined by the maximum length of the components"] # [doc = " of the critical factorization of `x`, i.e., `max(len(u), len(v))`).."] # [doc = ""] # [doc = " The above two cases are represented by the variants below. Each entails"] # [doc = " a different instantiation of the Two-Way search algorithm."] # [doc = ""] # [doc = " N.B. If we could find a way to compute the exact period in all cases,"] # [doc = " then we could collapse this case analysis and simplify the algorithm. The"] # [doc = " Two-Way paper suggests this is possible, but more reading is required to"] # [doc = " grok why the authors didn't pursue that path."] # [derive (Clone , Copy , Debug)] enum Shift { Small { period : usize } , Large { shift : usize } , }
    };
}

Shift!()